  cards.forEach(c=>{
    const show=(cat==='all'||c.dataset.cat===cat);
    if(show&&c.classList.contains('hidden-cat')){
      c.classList.remove('hidden-cat');
      c.classList.add('fading');
      requestAnimationFrame(()=>requestAnimationFrame(()=>c.classList.remove('fading')));
    }else if(!show&&!c.classList.contains('hidden-cat')){
      c.classList.add('fading');
      setTimeout(()=>{c.classList.add('hidden-cat');c.classList.remove('fading');},250);
    }
  });
}));

/* ─── ORDEN POR FECHA ─── */
const grid=document.getElementById('blog-grid');
function sortCards(dir){
  const sorted=[...grid.querySelectorAll('.post-card')].sort((a,b)=>{
    return dir==='asc'
      ? a.dataset.date.localeCompare(b.dataset.date)
      : b.dataset.date.localeCompare(a.dataset.date);
  });
  sorted.forEach(c=>grid.appendChild(c));
}
document.getElementById('sort-select').addEventListener('change',function(){sortCards(this.value);});
sortCards(document.getElementById('sort-select').value);

/* ─── MODALES ─── */
let currentModal=null;
function openModal(id){
  const m=document.getElementById(id);
  currentModal=m;
  m.classList.add('open');
  requestAnimationFrame(()=>requestAnimationFrame(()=>m.classList.add('visible')));
  document.body.style.overflow='hidden';
}
function closeModal(){
  if(!currentModal)return;
  const m=currentModal;
  m.classList.remove('visible');
  setTimeout(()=>{m.classList.remove('open');},250);
  document.body.style.overflow='';
  currentModal=null;
}
document.querySelectorAll('.modal-overlay').forEach(o=>{
  o.addEventListener('click',e=>{if(e.target===o)closeModal();});
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
</script>
</body>
